import{a as e,c as t,d as n,l as r,m as i,p as a,s as o,t as s,u as c}from"./app-BsOuDHI-.js";var l=JSON.parse(`{"path":"/documentation/quartz-4.x/cron-expressions.html","title":"Cron Expression Reference","lang":"en-US","frontmatter":{"title":"Cron Expression Reference"},"git":{"updatedTime":1788441191000,"contributors":[{"name":"Marko Lahma","username":"","email":"marko.lahma@gmail.com","commits":1},{"name":"Claude Fable 5.1","username":"","email":"noreply@anthropic.com","commits":1}],"changelog":[{"hash":"8dee9f767ead84b6e47c023533864d1d3e3178ae","time":1788441191000,"email":"marko.lahma@gmail.com","author":"Marko Lahma","message":"The release post carries the day 4.0.0 shipped","coAuthors":[{"name":"Claude Fable 5.1","email":"noreply@anthropic.com"}]}]},"filePathRelative":"documentation/quartz-4.x/cron-expressions.md"}`),u={name:`cron-expressions.md`},d={class:`hint-container tip`};function f(s,l,u,f,p,m){let h=a(`RouteLink`);return n(),o(`div`,null,[l[28]||=t(`<h2 id="introduction" tabindex="-1"><a class="header-anchor" href="#introduction"><span>Introduction</span></a></h2><p>cron is a UNIX tool that has been around for a long time, so its scheduling capabilities are powerful and proven. The CronTrigger class is based on the scheduling capabilities of cron.</p><p>CronTrigger uses &quot;cron expressions&quot;, which are able to create firing schedules such as: &quot;At 8:00am every Monday through Friday&quot; or &quot;At 1:30am every last Friday of the month&quot;.</p><p>Cron expressions are powerful, but can be pretty confusing. This tutorial aims to take some of the mystery out of creating a cron expression, giving users a resource which they can visit before having to ask in a forum or mailing list.</p><h2 id="format" tabindex="-1"><a class="header-anchor" href="#format"><span>Format</span></a></h2><p>A cron expression is a string comprised of 6 or 7 fields separated by white space. Fields can contain any of the allowed values, along with various combinations of the allowed special characters for that field. The fields are as follows:</p><table><thead><tr><th><strong>Field Name</strong></th><th><strong>Mandatory</strong></th><th><strong>Allowed Values</strong></th><th><strong>Allowed Special Characters</strong></th></tr></thead><tbody><tr><td>Seconds</td><td>YES</td><td>0-59</td><td>, - * / H</td></tr><tr><td>Minutes</td><td>YES</td><td>0-59</td><td>, - * / H</td></tr><tr><td>Hours</td><td>YES</td><td>0-23</td><td>, - * / H</td></tr><tr><td>Day of month</td><td>YES</td><td>1-31</td><td>, - * ? / L W H</td></tr><tr><td>Month</td><td>YES</td><td>1-12 or JAN-DEC</td><td>, - * / H</td></tr><tr><td>Day of week</td><td>YES</td><td>1-7 or SUN-SAT</td><td>, - * ? / L # H</td></tr><tr><td>Year</td><td>NO</td><td>empty, 1970-2099</td><td>, - * /</td></tr></tbody></table><p>So cron expressions can be as simple as this: <code>* * * * ? *</code></p><p>or more complex, like this: <code>0/5 14,18,3-39,52 * ? JAN,MAR,SEP MON-FRI 2002-2010</code></p><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>For easy generation of cron intervals using UI you can use some of these services:</p><ul><li><a href="https://www.freeformatter.com/cron-expression-generator-quartz.html" target="_blank" rel="noopener noreferrer">Cron Expression Generator &amp; Explainer</a></li><li><a href="http://www.cronmaker.com/" target="_blank" rel="noopener noreferrer">CronMaker</a></li></ul><p>NOTE: There are many cron standards/implementations. The results from some generators may not always be correct for Quartz.NET. A generator that emits the five-field Unix form can be read as written - see <a href="#the-unix-five-field-form">The Unix five-field form</a>.</p></div><h2 id="special-characters" tabindex="-1"><a class="header-anchor" href="#special-characters"><span>Special characters</span></a></h2><ul><li><p><code>*</code> (&quot;all values&quot;) - used to select all values within a field. For example, <code>*</code> in the minute field means &quot;every minute&quot;.</p></li><li><p><code>?</code> (&quot;no specific value&quot;) - allowed in the day-of-month and day-of-week fields, where it is a synonym for <code>*</code>: both say that the field names no days. Use it when you need to specify something in one of the two fields but not the other. For example, if I want my trigger to fire on a particular day of the month (say, the 10th), but don&#39;t care what day of the week that happens to be, I would put <code>10</code> in the day-of-month field, and <code>?</code> in the day-of-week field. See the examples below for clarification.</p></li><li><p><code>-</code> - used to specify ranges. For example, <code>10-12</code> in the hour field means &quot;the hours 10, 11 and 12&quot;.</p></li><li><p><code>,</code> - used to specify additional values. For example, <code>MON,WED,FRI</code> in the day-of-week field means &quot;the days Monday, Wednesday, and Friday&quot;.</p></li><li><p><code>/</code> - used to specify increments. For example, <code>0/15</code> in the seconds field means &quot;the seconds 0, 15, 30, and 45&quot;. And <code>5/15</code> in the seconds field means &quot;the seconds 5, 20, 35, and 50&quot;. You can also specify <code>/</code> after the <code>*</code> character - in this case <code>*</code> is equivalent to having <code>0</code> before the <code>/</code>. <code>1/3</code> in the day-of-month field means &quot;fire every 3 days starting on the first day of the month&quot;.</p></li><li><p><code>L</code> (&quot;last&quot;) - has different meaning in each of the two fields in which it is allowed. For example, the value <code>L</code> in the day-of-month field means &quot;the last day of the month&quot; - day 31 for January, day 28 for February on non-leap years. If used in the day-of-week field by itself, it simply means &quot;7&quot; or &quot;SAT&quot;. But if used in the day-of-week field after another value, it means &quot;the last xxx day of the month&quot; - for example <code>6L</code> means &quot;the last Friday of the month&quot;. You can also specify an offset from the last day of the month, such as <code>L-3</code> which would mean the third-to-last day of the calendar month. The <code>L</code> option can be used in a list, but there can only be one occurrence of the <code>L</code>. For example <code>1,15,L</code> would mean trigger on the 1st, 15th and Last Day of the month.</p></li><li><p><code>W</code> (&quot;weekday&quot;) - used to specify the weekday (Monday-Friday) nearest the given day. As an example, if you were to specify <code>15W</code> as the value for the day-of-month field, the meaning is: &quot;the nearest weekday to the 15th of the month&quot;. So if the 15th is a Saturday, the trigger will fire on Friday the 14th. If the 15th is a Sunday, the trigger will fire on Monday the 16th. If the 15th is a Tuesday, then it will fire on Tuesday the 15th. However if you specify <code>1W</code> as the value for day-of-month, and the 1st is a Saturday, the trigger will fire on Monday the 3rd, as it will not &#39;jump&#39; over the boundary of a month&#39;s days. The <code>W</code> character can only be specified when the day-of-month is a single day, not a range or list of days.</p></li></ul><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>The <code>L</code> and <code>W</code> characters can also be combined in the day-of-month field to yield <code>LW</code>, which translates to <em>&quot;last weekday of the month&quot;</em>. This field can also be used in a list, for example <code>1,15,LW</code> meaning 1st, 15th and Last Weekday of the month. <code>LW</code> supports an offset value, which will be calculated by first identifying last weekday, then subtracting the offset. for example <code>LW-2</code></p></div><ul><li><p><code>#</code> - used to specify &quot;the nth&quot; XXX day of the month. For example, the value of <code>6#3</code> in the day-of-week field means &quot;the third Friday of the month&quot; (day 6 = Friday and &quot;#3&quot; = the 3rd one in the month). Other examples: <code>2#1</code> = the first Monday of the month and <code>4#5</code> = the fifth Wednesday of the month. Note that if you specify <code>#5</code> and there is not 5 of the given day-of-week in the month, then no firing will occur that month.</p></li><li><p><code>@</code> - names a whole schedule instead of one field. <code>@daily</code> <em>is</em> the expression; there is nothing else in it. See <a href="#macros">Macros</a> below for the set.</p></li></ul><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>The legal characters and the names of months and days of the week are not case sensitive. MON is the same as mon.</p></div><h2 id="forms-the-parser-refuses" tabindex="-1"><a class="header-anchor" href="#forms-the-parser-refuses"><span>Forms the parser refuses</span></a></h2><p>Seven shapes parsed on 3.x and then meant something other than what they said — a special character was dropped on the floor, or a step degenerated. Each is a <code>FormatException</code> in 4.x, and the message names the expression that says what the author meant.</p><table><thead><tr><th style="text-align:left;">Written</th><th style="text-align:left;">What it used to mean</th><th style="text-align:left;">Write instead</th></tr></thead><tbody><tr><td style="text-align:left;"><code>1-5W</code></td><td style="text-align:left;">the <code>W</code> was dropped, leaving <code>1-5</code></td><td style="text-align:left;"><code>1W,2W,3W,4W,5W</code>, or drop the <code>W</code>. <code>W</code> applies to a single day, not a range or a list</td></tr><tr><td style="text-align:left;"><code>? * L-3</code>, <code>? * LW</code></td><td style="text-align:left;">the suffix was dropped, leaving Saturday</td><td style="text-align:left;"><code>L-3</code> and <code>LW</code> belong to day-of-month. A bare <code>L</code> in day-of-week is still Saturday</td></tr><tr><td style="text-align:left;"><code>MON,FRI#3</code></td><td style="text-align:left;">the third <strong>Monday</strong>; the Friday was never fired</td><td style="text-align:left;">one trigger per day, or drop the <code>#</code>. <code>#</code> applies to the whole field</td></tr><tr><td style="text-align:left;"><code>5C</code>, <code>1C</code></td><td style="text-align:left;"><code>5</code> / <code>1</code> — <code>C</code> (&quot;calendar&quot;) was never implemented</td><td style="text-align:left;"><code>WithCalendarName</code>, which is what a calendar is for</td></tr><tr><td style="text-align:left;"><code>*/0</code>, <code>5/0</code>, <code>0-10/0</code></td><td style="text-align:left;">no step at all</td><td style="text-align:left;"><code>*</code> for every value, or a step of 1 or more</td></tr><tr><td style="text-align:left;"><code>0-10/120</code></td><td style="text-align:left;">an unchecked step; <code>0/120</code> was already rejected</td><td style="text-align:left;">a step inside the field&#39;s range</td></tr><tr><td style="text-align:left;"><code>MON/2</code></td><td style="text-align:left;">every second week, with no stable phase</td><td style="text-align:left;"><code>MON,WED,FRI</code> for a step through the week, or <code>RecurrenceScheduleBuilder.Create(&quot;FREQ=WEEKLY;INTERVAL=2;BYDAY=MO&quot;)</code> for every second Monday</td></tr></tbody></table>`,18),e(`p`,null,[l[1]||=e(`code`,null,`MON/2`,-1),l[2]||=r(` is the one that changes a schedule rather than only a spelling. A textual day-of-week followed by `,-1),l[3]||=e(`code`,null,`/`,-1),l[4]||=r(` meant "every N weeks", while the numeric `,-1),l[5]||=e(`code`,null,`2/2`,-1),l[6]||=r(` beside it meant an ordinary step — two readings of one grammar. The fortnight also had no phase to keep: it counted whole weeks from wherever the search happened to start, so a misfire, a restart, a failover or a dashboard query recomputed it from a different day and moved it. It is rejected rather than quietly re-read as a step, because re-reading it would turn a fortnightly job into a thrice-weekly one — 26 fires a year become 156 — with nothing logged. `,-1),c(h,{to:`/documentation/quartz-4.x/tutorial/recurrencetrigger.html`},{default:i(()=>[...l[0]||=[e(`code`,null,`RecurrenceTrigger`,-1)]]),_:1}),l[7]||=r(` anchors the interval on the trigger's start time, so the fortnight belongs to the trigger.`,-1)]),e(`p`,null,[l[9]||=r(`If a database may hold one of these expressions, audit it before upgrading: `,-1),c(h,{to:`/documentation/quartz-4.x/migration-guide.html#before-you-upgrade`},{default:i(()=>[...l[8]||=[r(`Before you upgrade`,-1)]]),_:1}),l[10]||=r(` has the query.`,-1)]),l[29]||=t(`<h2 id="macros" tabindex="-1"><a class="header-anchor" href="#macros"><span>Macros</span></a></h2><p>The <code>@</code> macros are the ones Unix cron has had since Vixie&#39;s, and they mean the same thing here:</p><table><thead><tr><th style="text-align:left;"><strong>Macro</strong></th><th style="text-align:left;"><strong>Expands to</strong></th><th style="text-align:left;"><strong>Meaning</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><code>@yearly</code>, <code>@annually</code></td><td style="text-align:left;"><code>0 0 0 1 1 ?</code></td><td style="text-align:left;">Midnight on 1 January</td></tr><tr><td style="text-align:left;"><code>@monthly</code></td><td style="text-align:left;"><code>0 0 0 1 * ?</code></td><td style="text-align:left;">Midnight on the 1st of every month</td></tr><tr><td style="text-align:left;"><code>@weekly</code></td><td style="text-align:left;"><code>0 0 0 ? * SUN</code></td><td style="text-align:left;">Midnight every Sunday</td></tr><tr><td style="text-align:left;"><code>@daily</code>, <code>@midnight</code></td><td style="text-align:left;"><code>0 0 0 * * ?</code></td><td style="text-align:left;">Midnight every day</td></tr><tr><td style="text-align:left;"><code>@hourly</code></td><td style="text-align:left;"><code>0 0 * * * ?</code></td><td style="text-align:left;">The top of every hour</td></tr></tbody></table><p>A macro needs no dialect and no opt-in, so it works wherever an expression string is read - in code, in an XML scheduling file&#39;s <code>&lt;cron-expression&gt;@daily&lt;/cron-expression&gt;</code>, in the dashboard&#39;s expression box and over the HTTP API:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">ITrigger</span> trigger <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;nightly&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span><span class="token string">&quot;@daily&quot;</span><span class="token punctuation">)</span> <span class="token comment">// stored, and shown, as &quot;0 0 0 * * ?&quot;</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The expansion is what gets stored: a trigger written with <code>@daily</code> reports its expression as <code>0 0 0 * * ?</code>.</p><p><code>@reboot</code> is rejected by name - a scheduler has no reboot to fire on, so schedule the work at startup instead - and any other <code>@name</code> is rejected with the list above. There is deliberately no <code>@every_minute</code> or <code>@every_second</code>: <code>0 * * * * ?</code> is already short, and where the point is to spread load, <a href="#h-hash-for-load-distribution"><code>H</code></a> does it deterministically.</p><h2 id="the-unix-five-field-form" tabindex="-1"><a class="header-anchor" href="#the-unix-five-field-form"><span>The Unix five-field form</span></a></h2><p>A cron expression copied from a crontab, a Kubernetes <code>CronJob</code> or almost any online generator has <strong>five</strong> fields rather than six: it has no seconds field, and it numbers the days of the week 0-7 from Sunday rather than 1-7. Quartz reads that form when you ask it to, with <code>CronFormat.Unix</code>:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token comment">// &quot;at 04:30 on Mondays&quot;, written the way crontab writes it</span></span>
<span class="line"><span class="token class-name">CronExpression</span> expression <span class="token operator">=</span> CronExpression<span class="token punctuation">.</span><span class="token function">Parse</span><span class="token punctuation">(</span><span class="token string">&quot;30 4 * * 1&quot;</span><span class="token punctuation">,</span> CronFormat<span class="token punctuation">.</span>Unix<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ...and held the way Quartz writes it: &quot;0 30 4 ? * MON&quot;</span></span>
<span class="line"><span class="token class-name"><span class="token keyword">string</span></span> canonical <span class="token operator">=</span> expression<span class="token punctuation">.</span>CronExpressionString<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The format is a way of reading the string, and that is all it is. There are three doors - <code>CronExpression.Parse</code>, <code>CronExpression.TryParse</code> and <code>CronScheduleBuilder.Create</code> - and past them the expression is an ordinary <code>CronExpression</code>:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">ITrigger</span> trigger <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;weekday-report&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithSchedule</span><span class="token punctuation">(</span>CronScheduleBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token string">&quot;15 10 * * 1-5&quot;</span><span class="token punctuation">,</span> CronFormat<span class="token punctuation">.</span>Unix<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// WithCronSchedule has no format overload; compose one when you need its other options</span></span>
<span class="line"><span class="token class-name">ITrigger</span> composed <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;weekday-report-2&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span>CronExpression<span class="token punctuation">.</span><span class="token function">Parse</span><span class="token punctuation">(</span><span class="token string">&quot;15 10 * * 1-5&quot;</span><span class="token punctuation">,</span> CronFormat<span class="token punctuation">.</span>Unix<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>A time zone composes the same way: <code>CronExpression.Parse(s, CronFormat.Unix).WithTimeZone(tz)</code>.</p><table><thead><tr><th style="text-align:left;"><strong>Crontab</strong></th><th style="text-align:left;"><strong>Read as</strong></th><th style="text-align:left;"><strong>Meaning</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><code>30 4 * * 1</code></td><td style="text-align:left;"><code>0 30 4 ? * MON</code></td><td style="text-align:left;">04:30 every Monday</td></tr><tr><td style="text-align:left;"><code>0 12 1 * *</code></td><td style="text-align:left;"><code>0 0 12 1 * ?</code></td><td style="text-align:left;">Noon on the 1st of every month</td></tr><tr><td style="text-align:left;"><code>* * * * *</code></td><td style="text-align:left;"><code>0 * * * * ?</code></td><td style="text-align:left;">Every minute</td></tr><tr><td style="text-align:left;"><code>15 10 * * 1-5</code></td><td style="text-align:left;"><code>0 15 10 ? * MON-FRI</code></td><td style="text-align:left;">10:15 on weekdays</td></tr><tr><td style="text-align:left;"><code>0 0 * * 0-6</code></td><td style="text-align:left;"><code>0 0 0 * * ?</code></td><td style="text-align:left;">Midnight every day - <code>0-6</code> is the whole week</td></tr><tr><td style="text-align:left;"><code>0 0 * * 5-1</code></td><td style="text-align:left;"><code>0 0 0 ? * FRI-MON</code></td><td style="text-align:left;">Midnight Friday through Monday</td></tr><tr><td style="text-align:left;"><code>0 0 13 * 5</code></td><td style="text-align:left;"><code>0 0 0 13 * FRI</code></td><td style="text-align:left;">The 13th <strong>and</strong> every Friday - both fields name days</td></tr></tbody></table><p>Two things differ between the dialects and nothing else does. The <strong>layout</strong>: five fields, minutes first, with no seconds and no year. The <strong>day-of-week numbering</strong>: 0-7 with both 0 and 7 meaning Sunday, so <code>1-5</code> is Monday to Friday as it is in crontab, and <code>5</code> is Friday rather than the Thursday the same digit means in a Quartz expression. Everything above is one grammar - <code>L</code>, <code>W</code> and <code>#</code> all work inside the five-field layout, and <code>L</code> alone in day-of-week still means Saturday, because it is not a number and so has nothing to renumber.</p><div class="hint-container tip"><p class="hint-container-title"><code>H</code> composes with the Unix form</p><p><code>CronScheduleBuilder.Create(expression, CronFormat.Unix)</code> reads an <code>H</code> in the five-field form: it rewrites to the Quartz form first and then defers the hash to the trigger&#39;s identity, so <code>Create(&quot;H 4 * * 1&quot;, CronFormat.Unix)</code> on a trigger identified as <code>nightly</code> comes out as <code>0 13 4 ? * MON</code>. <a href="#h-hash-for-load-distribution"><code>ParseWithHash</code></a> and <code>TryParseWithHash</code> take a format beside the hash key and run the same rewrite first, so <code>ParseWithHash(&quot;H 4 * * 1&quot;, CronFormat.Unix, &quot;nightly&quot;)</code> is that same expression without a trigger to hang it on. Because the rewrite runs first, an <code>H</code> in a five-field day-of-week is hashed over Quartz&#39;s 1-7 rather than crontab&#39;s 0-7 and can never land on a day the renumbering would have moved.</p><p><code>CronExpression.Parse</code> and <code>TryParse</code> take a format but no hash key, so there is nothing for <code>H</code> to hash against. <code>ResolveHash</code> still takes a hash key but no format: it answers with a string rather than an expression, so it stays a Quartz-form operation, and a five-field expression is rejected there with the six-field advice. Resolve through <code>ParseWithHash</code> instead.</p></div><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>The expression is <strong>normalised</strong> to the canonical Quartz form, and the original text is not recoverable. <code>CronExpressionString</code>, the dashboard, the HTTP API and <code>QRTZ_CRON_TRIGGERS.CRON_EXPRESSION</code> all show <code>0 30 4 ? * MON</code> for a trigger written as <code>30 4 * * 1</code>. That is deliberate: a stored string that parses only under a flag the store does not persist would be a trap, so there is no format column and there will not be one. It is the same trade as the uppercasing that has always turned <code>mon-fri</code> into <code>MON-FRI</code>.</p><p>The consequence is that the format is a parse-time argument only: the XML schema, the HTTP API and the dashboard do not take one, so a five-field expression is something you write in C#, not something you store. The macros above have no such limit.</p></div><p>There is no auto-detection, and the field count alone does not choose the dialect. Letting it would make a <em>dropped</em> field silent: <code>0 0 12 * * ?</code> without its month field is <code>0 0 12 * ?</code>, a well-formed crontab line meaning midnight on the 12th rather than noon every day. The same digit also names a different day in each dialect. So Quartz asks, and the error a five-field expression gets when nobody asked names the method that does read it.</p><h3 id="an-expression-copied-from-spring" tabindex="-1"><a class="header-anchor" href="#an-expression-copied-from-spring"><span>An expression copied from Spring</span></a></h3><div class="hint-container caution"><p class="hint-container-title">A Spring expression with a numeric day-of-week schedules the wrong day</p><p>Spring&#39;s <code>@Scheduled(cron = …)</code> is <strong>six</strong> fields with seconds first, exactly the shape of a Quartz expression — so Quartz accepts it without complaint. But Spring numbers the days of the week the Unix way, 0-7 with both 0 and 7 meaning Sunday, where Quartz numbers them 1-7 starting at Sunday. Every numeric day therefore reads one day earlier than it was written, silently, and has on every version of Quartz ever shipped.</p><table><thead><tr><th style="text-align:left;"><code>@Scheduled(cron = …)</code></th><th style="text-align:left;">Spring fires</th><th style="text-align:left;">Quartz reads it as</th></tr></thead><tbody><tr><td style="text-align:left;"><code>0 0 9 * * 1</code></td><td style="text-align:left;">09:00 on Mondays</td><td style="text-align:left;">09:00 on <strong>Sundays</strong></td></tr><tr><td style="text-align:left;"><code>0 0 9 * * 1-5</code></td><td style="text-align:left;">09:00 Monday to Friday</td><td style="text-align:left;">09:00 <strong>Sunday to Thursday</strong></td></tr><tr><td style="text-align:left;"><code>0 0 9 * * 6</code></td><td style="text-align:left;">09:00 on Saturdays</td><td style="text-align:left;">09:00 on <strong>Fridays</strong></td></tr><tr><td style="text-align:left;"><code>0 0 9 * * MON-FRI</code></td><td style="text-align:left;">09:00 Monday to Friday</td><td style="text-align:left;">09:00 Monday to Friday</td></tr></tbody></table><p><strong>Write the day as a name.</strong> <code>SUN</code>, <code>MON</code>, <code>TUE</code>, <code>WED</code>, <code>THU</code>, <code>FRI</code> and <code>SAT</code> mean the same day in Spring, in crontab and in Quartz, and Spring accepts them too — so a named expression is the one that survives being pasted in either direction. The last row above is the same schedule under both readings.</p><p>There is no <code>CronFormat.Spring</code>, and there is no detection of one either. The two six-field dialects are <em>the same shape</em>, so nothing about the string can tell them apart — which is the structural reason <a href="#the-unix-five-field-form">the format is stated rather than sniffed</a>. A <code>CronFormat.Spring</code> member can be added later without breaking anything, and it is filed for 4.1; auto-detection could never be added, because by then the existing reading of a six-field expression is the one people&#39;s schedules depend on.</p></div><h3 id="if-your-expressions-came-from-another-net-cron-library" tabindex="-1"><a class="header-anchor" href="#if-your-expressions-came-from-another-net-cron-library"><span>If your expressions came from another .NET cron library</span></a></h3><p>Cronos and NCrontab are crontab-derived, and an expression written for either parses here — six fields have the same shape. Almost all of them also fire at the same instants. Two things differ, and both are silent, because the expression is perfectly valid Quartz cron; it simply means something else.</p><p><strong>The day-of-week numbering.</strong> Quartz numbers <code>1-7</code> with Sunday <code>1</code>; those libraries number <code>0-6</code> with Sunday <code>0</code>, and crontab itself <code>0-7</code> with both ends Sunday. So <code>0 0 2 * * 1</code> is 02:00 on <strong>Sunday</strong> here and 02:00 on <strong>Monday</strong> there — the same divergence <a href="#an-expression-copied-from-spring">a Spring expression has</a>, and the same answer: write the day as a name. <code>SUN</code> through <code>SAT</code> mean the same day in every one of these dialects.</p><p><strong>Both day fields restricted.</strong> Quartz fires on the <strong>union</strong> of day-of-month and day-of-week, which is crontab&#39;s rule; Cronos takes their intersection. <code>0 0 2 5 * MON</code> is &quot;the 5th, and every Monday&quot; here and &quot;the 5th, if it is a Monday&quot; there. Putting <code>?</code> in one of the two fields says which one is in charge and settles it.</p><p>Everything else carries across. Searching from <code>2026-08-21T00:00:00Z</code>, against Cronos 0.11.0:</p><table><thead><tr><th style="text-align:left;">Expression</th><th style="text-align:left;">Quartz</th><th style="text-align:left;">Cronos</th><th style="text-align:left;"></th></tr></thead><tbody><tr><td style="text-align:left;"><code>0 0 2 * * MON</code></td><td style="text-align:left;">2026-08-24 02:00</td><td style="text-align:left;">2026-08-24 02:00</td><td style="text-align:left;">same</td></tr><tr><td style="text-align:left;"><code>0 0 7 * * *</code></td><td style="text-align:left;">2026-08-21 07:00</td><td style="text-align:left;">2026-08-21 07:00</td><td style="text-align:left;">same</td></tr><tr><td style="text-align:left;"><code>0 0 */1 * * *</code></td><td style="text-align:left;">2026-08-21 01:00</td><td style="text-align:left;">2026-08-21 01:00</td><td style="text-align:left;">same</td></tr><tr><td style="text-align:left;"><code>0 */15 * * * *</code></td><td style="text-align:left;">2026-08-21 00:15</td><td style="text-align:left;">2026-08-21 00:15</td><td style="text-align:left;">same</td></tr><tr><td style="text-align:left;"><code>0 30 6 * * MON,TUE,WED,THU,FRI</code></td><td style="text-align:left;">2026-08-21 06:30</td><td style="text-align:left;">2026-08-21 06:30</td><td style="text-align:left;">same</td></tr><tr><td style="text-align:left;"><code>0 0 2 * * 1</code></td><td style="text-align:left;">2026-08-23 (<strong>Sunday</strong>)</td><td style="text-align:left;">2026-08-24 (<strong>Monday</strong>)</td><td style="text-align:left;"><strong>differ</strong></td></tr><tr><td style="text-align:left;"><code>0 0 2 5 * MON</code></td><td style="text-align:left;">2026-08-24 (union)</td><td style="text-align:left;">2026-10-05 (intersection)</td><td style="text-align:left;"><strong>differ</strong></td></tr></tbody></table><p>A <strong>five</strong>-field expression from one of those libraries is a different matter: <code>CronFormat.Unix</code> reads it and renumbers the days for you, so <code>CronExpression.Parse(&quot;0 2 * * 1&quot;, CronFormat.Unix)</code> is Monday, as its author meant. See <a href="#the-unix-five-field-form">The Unix five-field form</a>.</p>`,27),e(`div`,d,[l[18]||=e(`p`,{class:`hint-container-title`},`Upgrading from 3.x with such an expression in the database`,-1),e(`p`,null,[l[12]||=r(`3.x required `,-1),l[13]||=e(`code`,null,`?`,-1),l[14]||=r(` in exactly one day field, so an expression with two restricted day fields was `,-1),l[15]||=e(`em`,null,`rejected`,-1),l[16]||=r(` on the way in. It stores and fires on 4.0. The migration guide has an audit for finding the two shapes above among the expressions you already hold: `,-1),c(h,{to:`/documentation/quartz-4.x/migration-guide.html#if-your-expressions-came-from-another-cron-library`},{default:i(()=>[...l[11]||=[r(`If your expressions came from another cron library`,-1)]]),_:1}),l[17]||=r(`.`,-1)])]),l[30]||=t(`<h2 id="h-hash-for-load-distribution" tabindex="-1"><a class="header-anchor" href="#h-hash-for-load-distribution"><span>H (hash) for load distribution</span></a></h2><p>The <code>H</code> symbol (for &quot;hash&quot;) can be used in place of a specific value to spread scheduled tasks evenly across time. When many triggers share an identical cron expression such as <code>0 0 0 * * ?</code> (midnight daily), they all fire simultaneously, causing resource spikes.</p><p><code>H</code> resolves to a <strong>deterministic</strong> value derived from the trigger&#39;s identity (name and group). The value stays stable as long as the trigger identity doesn&#39;t change, but different triggers get different values, spreading load across the allowed range.</p><h3 id="syntax" tabindex="-1"><a class="header-anchor" href="#syntax"><span>Syntax</span></a></h3><table><thead><tr><th style="text-align:left;"><strong>Expression</strong></th><th style="text-align:left;"><strong>Meaning</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><code>H</code></td><td style="text-align:left;">Hash value within the full range of the field</td></tr><tr><td style="text-align:left;"><code>H(0-7)</code></td><td style="text-align:left;">Hash value constrained to the range 0 through 7</td></tr><tr><td style="text-align:left;"><code>H/15</code></td><td style="text-align:left;">Hash-derived offset, then repeat every 15 (e.g., 7, 22, 37, 52)</td></tr><tr><td style="text-align:left;"><code>H(0-29)/10</code></td><td style="text-align:left;">Hash-derived offset in 0-29, then repeat every 10 (e.g., 3, 13, 23)</td></tr></tbody></table><p><code>H</code> can appear in <strong>comma-separated lists</strong> alongside fixed values (e.g., <code>H,30,45</code>).</p><p><code>H</code> is <strong>not</strong> supported in the Year field, and cannot be combined with <code>L</code>, <code>W</code>, or <code>#</code>.</p><h3 id="hash-examples" tabindex="-1"><a class="header-anchor" href="#hash-examples"><span>Hash examples</span></a></h3><table><thead><tr><th style="text-align:left;"><strong>Expression</strong></th><th style="text-align:left;"><strong>Description</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><code>0 H H * * ?</code></td><td style="text-align:left;">Once per day at a hash-derived hour and minute</td></tr><tr><td style="text-align:left;"><code>0 H H(0-7) * * ?</code></td><td style="text-align:left;">Once per day between midnight and 7:59 AM</td></tr><tr><td style="text-align:left;"><code>0 H/15 * * * ?</code></td><td style="text-align:left;">Every 15 minutes, starting from a hash-derived offset</td></tr><tr><td style="text-align:left;"><code>H H H * * ?</code></td><td style="text-align:left;">Once per day at a unique second, minute, and hour</td></tr></tbody></table><h3 id="usage-with-triggerbuilder" tabindex="-1"><a class="header-anchor" href="#usage-with-triggerbuilder"><span>Usage with TriggerBuilder</span></a></h3><p>When using <code>H</code> through the builder API, the trigger identity is used as the hash seed. You <strong>must</strong> call <code>WithIdentity()</code> so the hash is derived from a stable, meaningful name rather than a random GUID:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">ITrigger</span> trigger <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;nightly-cleanup&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span><span class="token string">&quot;0 H H(0-7) * * ?&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>You can also provide an explicit hash key, which does not require a trigger identity. The key rides on the <code>CronExpression</code>, and <code>WithCronSchedule</code> takes one directly:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">ITrigger</span> trigger <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span>CronExpression<span class="token punctuation">.</span><span class="token function">ParseWithHash</span><span class="token punctuation">(</span><span class="token string">&quot;0 H H(0-7) * * ?&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;nightly-cleanup&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Or resolve the expression on its own with <code>CronExpression.ParseWithHash</code>, which is the parse the builder overload does for you. <code>CronExpression.TryParseWithHash</code> is the non-throwing form, for a key and an expression that both came from somewhere you do not control. Both take a <a href="#the-unix-five-field-form"><code>CronFormat</code></a> as their second argument when the expression is not written the Quartz way:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">CronExpression</span> expr <span class="token operator">=</span> CronExpression<span class="token punctuation">.</span><span class="token function">ParseWithHash</span><span class="token punctuation">(</span><span class="token string">&quot;0 H H(0-7) * * ?&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;nightly-cleanup&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">Tips</p><p><code>CronExpressionString</code> returns the <strong>resolved</strong> expression (e.g., <code>&quot;0 23 3 * * ?&quot;</code>) after H tokens are replaced with their computed values. This resolved form is what gets persisted to the database, ensuring stability across scheduler restarts.</p></div><h2 id="building-cron-expressions-programmatically" tabindex="-1"><a class="header-anchor" href="#building-cron-expressions-programmatically"><span>Building cron expressions programmatically</span></a></h2><p>When a schedule is assembled from user input - for example a scheduling UI that offers dropdowns instead of a free-form cron field - you can compose the expression with the fluent <code>CronExpressionBuilder</code> instead of concatenating strings:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">ITrigger</span> trigger <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;myTrigger&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithCronSchedule</span><span class="token punctuation">(</span>CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">WithSecond</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">WithMinuteIncrements</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">15</span><span class="token punctuation">)</span> <span class="token comment">// every 15 minutes</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">WithHourRange</span><span class="token punctuation">(</span><span class="token number">8</span><span class="token punctuation">,</span> <span class="token number">17</span><span class="token punctuation">)</span>        <span class="token comment">// between 8:00 and 17:59</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">OnWeekdays</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>               <span class="token comment">// &quot;0 0/15 8-17 ? * MON-FRI&quot;</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>WithCronSchedule</code> accepts the builder (or a built <code>CronExpression</code>) directly, so the chain closes without naming <code>CronScheduleBuilder</code>; call <code>Build()</code> yourself when you want the <code>CronExpression</code> as a value.</p><p>Each field offers a single value, list, range and increment form (e.g. <code>WithHour</code>, <code>WithHours</code>, <code>WithHourRange</code>, <code>WithHourIncrements</code>). A schedule that fires once a day sets three of those fields to say one thing, so <code>AtTime</code> sets them together from a <code>TimeOnly</code> — add the days it applies to beside it:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">AtTime</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">TimeOnly</span><span class="token punctuation">(</span><span class="token number">9</span><span class="token punctuation">,</span> <span class="token number">30</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// &quot;0 30 9 ? * *&quot;</span></span>
<span class="line"></span>
<span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">AtTime</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">TimeOnly</span><span class="token punctuation">(</span><span class="token number">9</span><span class="token punctuation">,</span> <span class="token number">30</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithDaysOfWeek</span><span class="token punctuation">(</span>DayOfWeek<span class="token punctuation">.</span>Monday<span class="token punctuation">,</span> DayOfWeek<span class="token punctuation">.</span>Thursday<span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// &quot;0 30 9 ? * MON,THU&quot;</span></span>
<span class="line"></span>
<span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">AtTime</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">TimeOnly</span><span class="token punctuation">(</span><span class="token number">9</span><span class="token punctuation">,</span> <span class="token number">30</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">WithDayOfMonth</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                                              <span class="token comment">// &quot;0 30 9 15 * ?&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Cron resolves to a whole second, so any sub-second part of the <code>TimeOnly</code> is ignored.</p><p>The special characters are available through dedicated methods:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">OnLastDayOfMonth</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                         <span class="token comment">// &quot;* * * L * ?&quot;</span></span>
<span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">OnNearestWeekdayOfMonth</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                <span class="token comment">// &quot;* * * 15W * ?&quot;</span></span>
<span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">OnNthDayOfWeekOfMonth</span><span class="token punctuation">(</span>DayOfWeek<span class="token punctuation">.</span>Friday<span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &quot;* * * ? * FRI#3&quot;</span></span>
<span class="line">CronExpressionBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">OnLastDayOfWeekOfMonth</span><span class="token punctuation">(</span>DayOfWeek<span class="token punctuation">.</span>Friday<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// &quot;* * * ? * FRIL&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>A few rules to be aware of:</p><ul><li>Unconfigured fields default to <code>*</code> (every value).</li><li>Each field can be configured only once; configuring it again throws <code>InvalidOperationException</code>.</li><li>One expression carries one day field: the builder renders the unused one as <code>?</code> and throws if you configure both. That is the builder&#39;s own rule rather than cron&#39;s, because an expression naming both day fields fires on the union of the two (<code>0 15 10 1,2,3 * MON,FRI</code>), which <code>CronExpression.Parse</code> accepts - so write that one as text.</li><li>Values are validated eagerly against each field&#39;s allowed range, and <code>Build()</code> returns a fully validated <code>CronExpression</code>; use <code>ToString()</code> if you only need the expression string.</li><li>Days of the week are emitted using their textual names (<code>MON</code>, <code>FRI</code>, ...), so the produced expressions stay unambiguous across cron dialects that number weekdays differently.</li></ul><h2 id="examples" tabindex="-1"><a class="header-anchor" href="#examples"><span>Examples</span></a></h2><p>Here are some full examples:</p><table><thead><tr><th style="text-align:left;"><strong>Expression</strong></th><th style="text-align:left;"><strong>Meaning</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><code>0 0 12 * * ?</code></td><td style="text-align:left;">Fire at 12pm (noon) every day</td></tr><tr><td style="text-align:left;"><code>0 15 10 ? * *</code></td><td style="text-align:left;">Fire at 10:15am every day</td></tr><tr><td style="text-align:left;"><code>0 15 10 * * ?</code></td><td style="text-align:left;">Fire at 10:15am every day</td></tr><tr><td style="text-align:left;"><code>0 15 10 * * ? *</code></td><td style="text-align:left;">Fire at 10:15am every day</td></tr><tr><td style="text-align:left;"><code>0 15 10 * * ? 2005</code></td><td style="text-align:left;">Fire at 10:15am every day during the year 2005</td></tr><tr><td style="text-align:left;"><code>0 * 14 * * ?</code></td><td style="text-align:left;">Fire every minute starting at 2pm and ending at 2:59pm, every day</td></tr><tr><td style="text-align:left;"><code>0 0/5 14 * * ?</code></td><td style="text-align:left;">Fire every 5 minutes starting at 2pm and ending at 2:55pm, every day</td></tr><tr><td style="text-align:left;"><code>0 0/5 14,18 * * ?</code></td><td style="text-align:left;">Fire every 5 minutes starting at 2pm and ending at 2:55pm, AND fire every 5 minutes starting at 6pm and ending at 6:55pm, every day</td></tr><tr><td style="text-align:left;"><code>0 0-5 14 * * ?</code></td><td style="text-align:left;">Fire every minute starting at 2pm and ending at 2:05pm, every day</td></tr><tr><td style="text-align:left;"><code>0 10,44 14 ? 3 WED</code></td><td style="text-align:left;">Fire at 2:10pm and at 2:44pm every Wednesday in the month of March.</td></tr><tr><td style="text-align:left;"><code>0 15 10 ? * MON-FRI</code></td><td style="text-align:left;">Fire at 10:15am every Monday, Tuesday, Wednesday, Thursday and Friday</td></tr><tr><td style="text-align:left;"><code>0 15 10 15 * ?</code></td><td style="text-align:left;">Fire at 10:15am on the 15th day of every month</td></tr><tr><td style="text-align:left;"><code>0 15 10 L * ?</code></td><td style="text-align:left;">Fire at 10:15am on the last day of every month</td></tr><tr><td style="text-align:left;"><code>0 15 10 L-2 * ?</code></td><td style="text-align:left;">Fire at 10:15am on the 2nd-to-last last day of every month</td></tr><tr><td style="text-align:left;"><code>0 15 10 ? * 6L</code></td><td style="text-align:left;">Fire at 10:15am on the last Friday of every month</td></tr><tr><td style="text-align:left;"><code>0 15 10 ? * 6L 2002-2005</code></td><td style="text-align:left;">Fire at 10:15am on every last Friday of every month during the years 2002, 2003, 2004 and 2005</td></tr><tr><td style="text-align:left;"><code>0 15 10 ? * 6#3</code></td><td style="text-align:left;">Fire at 10:15am on the third Friday of every month</td></tr><tr><td style="text-align:left;"><code>0 0 12 1/5 * ?</code></td><td style="text-align:left;">Fire at 12pm (noon) every 5 days every month, starting on the first day of the month.</td></tr><tr><td style="text-align:left;"><code>0 11 11 11 11 ?</code></td><td style="text-align:left;">Fire every November 11th at 11:11am.</td></tr><tr><td style="text-align:left;"><code>0 15 10 1,2,3 * MON,FRI</code></td><td style="text-align:left;">Fire at 10:15am on the 1st, 2nd, 3rd of the month, and every Monday and Friday</td></tr><tr><td style="text-align:left;"><code>H H H * * ?</code></td><td style="text-align:left;">Fire once per day at a hash-derived second, minute, and hour (spread across triggers)</td></tr><tr><td style="text-align:left;"><code>0 H H(0-7) * * ?</code></td><td style="text-align:left;">Fire once per day between midnight and 7:59 AM, at a hash-derived time</td></tr><tr><td style="text-align:left;"><code>0 H/15 * * * ?</code></td><td style="text-align:left;">Fire every 15 minutes, starting from a hash-derived offset</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>Pay attention to the effects of <code>?</code> and <code>*</code> in the day-of-week and day-of-month fields. A day field written exactly <code>*</code> or <code>?</code> names no days, so it restricts nothing and the other day field decides: <code>0 15 10 1 * *</code> fires on the 1st of the month, and <code>0 15 10 * * MON</code> fires every Monday. Only when <strong>both</strong> fields name days does the expression fire on the union of the two, as <code>0 15 10 1,2,3 * MON,FRI</code> above does; when neither names days, every day matches. This is the Unix <code>crontab(5)</code> rule - some other cron implementations intersect the two fields instead, so an expression copied from one of those fires more often here than it did there.</p></div><h2 id="daylight-saving-time" tabindex="-1"><a class="header-anchor" href="#daylight-saving-time"><span>Daylight saving time</span></a></h2><p>A cron expression names a wall-clock time, and a daylight saving transition is exactly the event that makes a wall clock ambiguous or missing. <strong>Nothing is skipped and nothing is fired twice</strong>, but it is worth knowing which instant is chosen, and the answer depends on whether the expression names a fixed time of day or an interval.</p><p>A <strong>fixed-time</strong> expression is one whose second, minute and hour fields are plain values or comma lists of plain values - <code>0 30 2 * * ?</code>, <code>0 0,30 2 * * ?</code>:</p><ul><li>A wall-clock time the clocks <strong>skip</strong> fires once, at the <strong>end of the gap</strong> - the instant the clocks moved. A daily <code>0 30 2 * * ?</code> over a 02:00-03:00 spring-forward gap fires at 03:00. Every wall clock the gap swallowed names that one instant, so an expression matching several of them still fires once. This is the instant the expression itself matches: <code>IsSatisfiedBy</code> agrees with the fire time, which is what makes it the right answer.</li><li>A wall-clock time that <strong>occurs twice</strong> on a fall-back day fires once, at the <strong>first</strong> of the two occurrences.</li></ul><p>An <strong>interval</strong> expression - one with a wildcard, a step or a range in the second, minute or hour field, such as <code>0 * * * * ?</code> or <code>0 0/30 * * * ?</code> - keeps firing through the repeated hour, so both passes of it run. Over a spring-forward gap the gap-end rule shows as an extra fire rather than a moved one: <code>0 30 * * * ?</code> fires at 03:00 for the occurrence the gap swallowed and again at 03:30 for the next hour&#39;s.</p><p>A <code>CronCalendar</code> written over the skipped hour excludes the gap&#39;s end for the same reason.</p><div class="hint-container warning"><p class="hint-container-title">Quartz 3.x behaves differently</p><p>On 3.x a skipped time is shifted forward by the transition&#39;s delta instead - the daily <code>0 30 2 * * ?</code> above fires at 03:30, an instant its own expression does not match - and an interval expression fires the repeated hour only once, so an &quot;every minute&quot; schedule silently loses an hour of real time each autumn.</p></div>`,39),e(`p`,null,[l[21]||=r(`Whatever the schedule, `,-1),l[22]||=e(`strong`,null,`name the time zone`,-1),l[23]||=r(`: an expression with none uses `,-1),l[24]||=e(`code`,null,`TimeZoneInfo.Local`,-1),l[25]||=r(`, which is the developer's machine in development and very often UTC in a container. `,-1),c(h,{to:`/documentation/best-practices.html#daylight-saving-clock-changes-and-cluster-skew`},{default:i(()=>[...l[19]||=[r(`Daylight saving, clock changes and cluster skew`,-1)]]),_:1}),l[26]||=r(` covers the choice of trigger family, and the `,-1),c(h,{to:`/documentation/faq.html#daylight-saving-time-and-triggers`},{default:i(()=>[...l[20]||=[r(`FAQ`,-1)]]),_:1}),l[27]||=r(` has the longer treatment.`,-1)])])}var p=s(u,[[`render`,f]]);export{l as _pageData,p as default};